CREATE TABLE IF NOT EXISTS usage_record(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, api_key VARCHAR(100), key_label VARCHAR(80), requested_model VARCHAR(160), model VARCHAR(160), provider VARCHAR(50), status INT, prompt_tokens INT, completion_tokens INT, cost DOUBLE, cost_source VARCHAR(40) DEFAULT 'estimated', cache_hit BOOLEAN, fallback BOOLEAN, latency_ms BIGINT, upstream_id VARCHAR(160), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS semantic_cache(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, api_key VARCHAR(100), normalized_prompt VARCHAR(4000), answer CLOB, model VARCHAR(100), prompt_tokens INT, completion_tokens INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
